#include<bits/stdc++.h>using namespace std; int main() {     int t;     cin>>t;     while(t--)     {         int n;         cin>>n;         vector<int>a(n);         set<int>s;         for(int i=0;i<n;i++)          {             cin>>a[i];             s.insert(a[i]);         }         sort(a.rbegin(),a.rend());         if(a[0]==a[1]) swap(a[0],a[n-1]);         if(s.size()==1) cout<<"NO\n";         else         {             cout<<"YES\n";             for(int i=0;i<n;i++) cout<<a[i]<<" ";             cout<<'\n';         }     }     return 0;}